                throw questionMediaError('原生图形内容或题目绑定已变化');
            const spec = JSON.parse(descriptor.contentSignature);
            const dataUrl = descriptor.kind === 'canvas' ? spec.dataUrl : await rasterizeSvg(spec,node.ownerDocument,signal,check);
            check();
