                        if(courseSubmitConfirmation(doc,owner).length) throw new Error('已有提交确认窗口，请人工核对后再开始');
                        // 必须在第一次点击前保存原 frame/测验标识，点击可能同步触发文档导航。
                        const frame=doc.defaultView.frameElement;
