                            const tree=courseFrameTree(owner);
                            // 不读取导航期间的旧完成页，也不把跨域/空文档当提交成功。
                            if(tree.inaccessible.length)return false;
                            let resultDoc;
                            try { resultDoc=frame?.isConnected?frame.contentDocument:doc; }
                            catch { return false; }
