        if(kind==='personal')return url.origin==='https://i.chaoxing.com'&&['/','/base'].includes(url.pathname)?'personal':null;
        if(!isCourseHomeURL(url)&&!isCourseStudyURL(url))return null;
        const identity=courseURLContext(url);
